#!/usr/bin/env python3
"""Add 30 more database pairs to upgrade_m.jsonl -- fixes the assertion error"""
import json, pathlib

OUT = pathlib.Path('/workspace/data_upgrades')
OUT.parent.mkdir(parents=True, exist_ok=True)

pairs = [
("Explain database index types and when to use each.", "Index types: B-tree (default in Postgres/MySQL): balanced tree structure; efficient for equality, range queries, ORDER BY, and LIKE 'prefix%'; covers most use cases. Hash index: stores hash of the indexed value; optimal for equality only (=); faster than B-tree for equality on high-cardinality columns; no range or ordering support. GIN (Generalised Inverted Index): indexes composite values (arrays, JSON, full-text search vectors); use for jsonb columns, array containment queries, and tsvector (full-text search). GiST (Generalised Search Tree): spatial data (PostGIS), range types, nearest-neighbour search; more flexible than B-tree but slower updates. BRIN (Block Range INdex): stores min/max value per range of pages; extremely small; efficient for naturally ordered columns (timestamp, insert-order id) on very large tables; not useful for random access patterns. Partial index: index rows matching a WHERE condition; reduces index size; example: CREATE INDEX idx_active_users ON users(email) WHERE deleted_at IS NULL. Composite index: multiple columns; column order matters (leftmost prefix rule: index on (a,b,c) supports queries on (a), (a,b), (a,b,c) but not (b) alone). Covering index (INCLUDE): add non-indexed columns to the index leaf nodes to enable index-only scans."),
("How does VACUUM work in PostgreSQL and why is it critical?", "PostgreSQL uses MVCC (Multi-Version Concurrency Control): when a row is updated or deleted, the old version is marked dead (not immediately removed) to support concurrent readers still referencing it. VACUUM reclaims this dead tuple space. Two forms: VACUUM (non-blocking): marks dead tuple space as reusable within the same page; does not immediately return space to the OS; can run concurrently with reads and writes. VACUUM FULL: rewrites the entire table to a new heap file, returning space to the OS; requires an exclusive lock (blocks all reads and writes); use only during maintenance windows. AUTOVACUUM: background process automatically runs VACUUM when dead tuple ratio exceeds the threshold (autovacuum_vacuum_scale_factor default 20% of table size); configurable per-table for high-churn tables. Transaction ID wraparound: PostgreSQL uses 32-bit transaction IDs; after ~2 billion transactions, IDs wrap around; VACUUM FREEZE marks old tuples with a special frozen transaction ID, preventing wraparound; if VACUUM FREEZE doesn't run, PostgreSQL will force a stop (preventing any writes) to avoid data corruption. Monitoring: SELECT relname, n_dead_tup, last_autovacuum FROM pg_stat_user_tables WHERE n_dead_tup > 10000 ORDER BY n_dead_tup DESC; pg_bloat_check for index bloat."),
("What is database sharding and when should you use it?", "Sharding partitions a database horizontally across multiple server nodes, each holding a subset of the data. When to use: when a single node cannot handle read/write throughput or storage volume even after vertical scaling, indexing, and caching optimisations. Sharding strategies: (1) Range sharding: rows are distributed by a range of the shard key (users 1-1000000 on shard 1; 1000001-2000000 on shard 2); simple to implement; risk of hotspots if data is unevenly distributed or if all new data has sequential keys (monotonically increasing ID means all writes go to the last shard). (2) Hash sharding: shard_id = hash(shard_key) % num_shards; distributes data uniformly; eliminates hotspots; makes range queries inefficient (must query all shards). (3) Directory sharding: a lookup table maps keys to shards; maximum flexibility; the lookup table itself becomes a bottleneck and single point of failure. (4) Geographic sharding: users in the EU on EU shards (data residency); US users on US shards; natural boundary but may create hotspots by region. Costs of sharding: cross-shard JOIN queries require application-level aggregation; transactions spanning multiple shards require distributed transaction protocols (2PC); re-sharding (adding more shards) requires data migration; significantly increases operational complexity. Alternatives to sharding first: read replicas, caching layer (Redis), vertical scaling, table partitioning (Postgres native partitioning routes queries to partitions on the same node), connection pooling."),
("Explain ACID properties with concrete examples.", "ACID guarantees that database transactions process reliably: Atomicity: a transaction is all-or-nothing; if any statement in the transaction fails, the entire transaction is rolled back as if it never happened. Example: a bank transfer (debit account A, credit account B); if the credit fails after the debit, the debit is rolled back; money is never lost in transit. Consistency: a transaction brings the database from one valid state to another; all constraints (foreign keys, unique constraints, check constraints) must be satisfied before a commit is accepted. Example: an order for a product with quantity 0 in stock is rejected because a check constraint requires quantity >= 0 after the update. Isolation: concurrent transactions are isolated from each other as if they ran serially; the level of isolation is configurable (see isolation levels); without isolation, dirty reads, non-repeatable reads, and phantom reads can occur. Example: two users simultaneously buying the last item in stock; without isolation, both could see quantity=1, both could decrement to 0, resulting in quantity=-1. Durability: once a transaction is committed, it is permanently stored even if the system crashes immediately after; achieved via write-ahead log (WAL) in Postgres, redo log in MySQL/InnoDB; the log is flushed to durable storage before the commit is acknowledged."),
("What is the difference between optimistic and pessimistic locking?", "Optimistic locking: assumes conflicts are rare; no lock is acquired when reading; instead, a version number or timestamp is read with the data; when updating, the write includes a check that the version hasn't changed since the read; if another transaction modified the row in the interim, the update fails and must be retried. Implementation: a version column (INTEGER or TIMESTAMP) incremented on every update; UPDATE items SET quantity=quantity-1, version=version+1 WHERE id=? AND version=?; if rows affected=0, a conflict occurred. Best for: high-read, low-conflict workloads (most web applications). Pessimistic locking: assumes conflicts are likely; acquires a lock when reading; other transactions must wait until the lock is released before accessing the same data. Implementation in SQL: SELECT ... FOR UPDATE acquires a row-level exclusive lock; the lock is held until the transaction commits or rolls back. Best for: high-contention scenarios (inventory reservation, seat booking) where you must guarantee consistency at the cost of throughput. Deadlock risk: pessimistic locking creates deadlock potential when two transactions each hold a lock the other needs; databases detect deadlocks and abort one transaction; the aborted transaction must be retried."),
("Explain database replication modes and their consistency trade-offs.", "Database replication modes: Synchronous replication: the primary waits for acknowledgement from at least one replica before confirming the commit to the application; guarantees zero data loss if the primary fails (replica has all committed data); increases write latency because the write must travel to the replica before returning. Asynchronous replication: the primary commits locally and acknowledges immediately; replication to replicas happens in the background; no added write latency; replica may be seconds or minutes behind the primary (replication lag); if the primary fails, committed data not yet replicated is lost. Semi-synchronous (MySQL): waits for one replica to receive the binary log entry (not necessarily apply it) before acknowledging; lower latency than fully synchronous; minimal data loss risk. Consensus-based replication (Raft, Paxos -- used in CockroachDB, TiDB, etcd): the write is accepted once a majority of nodes acknowledge it; provides strong consistency guarantees without requiring all nodes to respond; tolerates minority node failures. Choice: PostgreSQL streaming replication with synchronous_commit=on for zero-loss replicas; synchronous_commit=off or local for performance-critical paths that can tolerate potential data loss on crash. Monitoring: SELECT pg_replication_lag() or check pg_stat_replication.write_lag, flush_lag, replay_lag on the primary."),
("How do you design a schema for time-series data in PostgreSQL?", "Time-series schema design: Time-series data (metrics, IoT sensor readings, financial ticks, event logs) is characterised by: high insert volume, append-only writes, range queries by time, data retention policies. Native PostgreSQL approach: (1) Table design: CREATE TABLE metrics (time TIMESTAMPTZ NOT NULL, device_id INT NOT NULL, metric_name TEXT NOT NULL, value DOUBLE PRECISION NOT NULL); (2) Partitioning by time range: PARTITION BY RANGE (time); create monthly or weekly child partitions; old partitions can be dropped or archived without a DELETE scan; queries targeting a time range only touch relevant partitions (partition pruning). (3) Index: CREATE INDEX ON metrics(device_id, time DESC) for the common query pattern 'latest N values for device X'. (4) Compression: PostgreSQL 14+ supports table-level TOAST compression; columnar storage via cstore_fdw or columnar extension reduces storage for repetitive metric names. TimescaleDB extension: built on PostgreSQL; automatic time-based partitioning (hypertables); native compression (10-20x reduction for time-series); continuous aggregates (materialised views that auto-refresh); data retention policies (automatic partition drop after retention period). For very high throughput: time-series databases (InfluxDB, Prometheus, QuestDB) are optimised for this workload and outperform general-purpose databases; consider the trade-off between ecosystem integration (PostgreSQL) and raw performance."),
("Explain the N+1 query problem and how to solve it in an ORM context.", "The N+1 query problem occurs when code executes one query to fetch N records, then executes N additional queries to fetch related data for each record -- resulting in N+1 total queries instead of 1 or 2. Example in an ORM: fetching a list of 100 blog posts and then accessing each post's author: posts = Post.all; posts.each { |p| puts p.author.name } -- generates 1 query for all posts and 100 queries for each author (101 total). Correct approach: eager loading -- tell the ORM to include the association in the initial query using a JOIN or a second query: Post.includes(:author).all generates 2 queries (one for posts, one for authors fetched by IDs) or a single JOIN. Solutions by language/ORM: ActiveRecord (Rails): .includes(:author) or .eager_load(:author) (JOIN) or .preload(:author) (separate query). SQLAlchemy (Python): selectinload(Post.author) or joinedload(Post.author). Hibernate (Java): FETCH JOIN in JPQL or @BatchSize. Detection: monitor query logs; the pattern of repeated identical queries with different parameter values signals N+1. Tools: Bullet gem (Rails), Django Debug Toolbar (Django), Hibernate's statistics logging. For GraphQL APIs, N+1 is extremely common (each field resolver issues a query); solution: DataLoader (batches all identical queries within a single request lifecycle into a single database query)."),
("What is connection pooling and why is it essential for database performance?", "Connection pooling maintains a pool of pre-established database connections that are reused across application requests, rather than creating a new connection for every request. Why it matters: establishing a PostgreSQL or MySQL connection involves TCP handshake, authentication, and session setup -- typically 10-50ms; at 1000 requests/second, without pooling, the overhead is 10-50 seconds per second of connection time, which is impossible. Pooling maintains, say, 20 persistent connections that are checked out and returned by each application request; connection setup happens once at pool startup. Key pooler parameters: pool size (maximum concurrent connections; set based on what the database server can handle, not what the application wants -- Postgres default max_connections=100; each connection consumes ~10MB RAM; recommended pool size = (2 * CPU cores) + effective_spindle_count for compute-bound workloads). Min idle connections (connections maintained even during low traffic for fast response). Connection timeout (how long an application waits for a connection before failing; should be shorter than user-facing timeout). Connection lifetime (maximum age of a connection before it is closed and replaced; prevents stale connections). Pooling tools: PgBouncer (PostgreSQL-specific; lightweight; supports transaction pooling mode -- a connection is returned to the pool after each transaction, not each request session; most efficient mode); RDS Proxy (AWS-managed for Aurora/RDS); application-level pools (HikariCP for Java, asyncpg pool for Python, pg-pool for Node)."),
("Explain full-text search in PostgreSQL vs dedicated search engines.", "Full-text search in PostgreSQL: Built-in using tsvector (a processed token vector) and tsquery (a search query). Setup: ADD COLUMN search_vector TSVECTOR; UPDATE SET search_vector = to_tsvector('english', title || ' ' || body); CREATE INDEX ON articles USING GIN(search_vector). Query: SELECT * FROM articles WHERE search_vector @@ to_tsquery('english', 'database & security'); supports: stemming (searches for 'running' match 'run'); stop words; ranking (ts_rank and ts_rank_cd score relevance). Automatically update via trigger or generated column: search_vector TSVECTOR GENERATED ALWAYS AS (to_tsvector('english', coalesce(title,'') || ' ' || coalesce(body,''))) STORED. Limitations: no typo tolerance (fuzzy matching); no synonym expansion; no custom relevance tuning; limited language support; performance degrades at very high query volume. Dedicated search engines (Elasticsearch, OpenSearch, Typesense, Meilisearch): strengths: typo tolerance (fuzzy matching); faceted search (filter by category, price range); custom relevance scoring; real-time indexing with inverted index; horizontal scalability; multi-language analysers; vector search (semantic). Trade-offs: separate system to operate and keep in sync with the source of truth (PostgreSQL); eventual consistency; additional operational complexity. Choice: PostgreSQL FTS is excellent for internal tools, admin search, and applications that don't need typo tolerance. Dedicated search engine is necessary for user-facing search where search quality significantly affects user experience."),
("Explain database backup strategies -- how to back up PostgreSQL reliably.", "PostgreSQL backup strategies: (1) pg_dump (logical backup): exports SQL statements to recreate the database; pg_dump dbname > backup.sql or pg_dump -Fc dbname > backup.dump (custom format, faster restore, supports parallel restore with pg_restore -j 4); supports table, schema, and row-level filtering; backup is consistent to the moment pg_dump started. Restore: psql dbname < backup.sql or pg_restore -d dbname backup.dump. Limitation: slow for large databases; creates a point-in-time snapshot (not continuous). (2) pg_basebackup (physical backup): copies the entire data directory as a binary snapshot; used to create standby replicas and as the base for PITR (Point-in-Time Recovery). Command: pg_basebackup -h primary -D /backup/base -Ft -z -P. (3) WAL archiving + PITR: continuous archiving of WAL (Write-Ahead Log) files to object storage (S3); combined with a base backup, allows recovery to any point in time (not just the backup moment). Configure: archive_mode=on; archive_command='aws s3 cp %p s3://bucket/wal/%f'. To recover to a specific time: restore base backup + replay WAL segments up to the target timestamp. (4) Tools: pgBackRest (enterprise-grade backup tool with PITR, compression, encryption, cloud storage); Barman; Wal-E / Wal-G (WAL archiving to S3/GCS). Best practice: 3-2-1-1-0 rule applied to database: daily base backup + continuous WAL archiving; replicas in a second AZ; test restore quarterly (measure actual RTO)."),
("What is the CAP theorem and what does it mean for database selection?", "The CAP theorem states that a distributed data system can provide at most two of three guarantees simultaneously: Consistency (C): every read receives the most recent write or an error; all nodes see the same data at the same time. Availability (A): every request receives a non-error response (though it may not be the most recent data); the system is always up and responsive. Partition tolerance (P): the system continues to operate even when network partitions (communication failures between nodes) occur. Why all three are impossible: in a distributed system, network partitions are inevitable (not a theoretical choice but a practical reality); therefore, a distributed system must always tolerate partitions; the real choice is between Consistency and Availability during a partition event. CP systems (Consistent and Partition-tolerant): during a partition, the system refuses to respond rather than return potentially stale data; examples: HBase, Zookeeper, MongoDB (with read concern majority), etcd. Use for: financial transactions, inventory systems, any use case where stale reads would cause incorrect decisions. AP systems (Available and Partition-tolerant): during a partition, the system returns the best available data (which may be stale); examples: Cassandra, CouchDB, DynamoDB (with eventual consistency). Use for: social feeds, analytics counters, recommendation systems where temporary staleness is acceptable. PACELC extension: in absence of a partition (E), a system still trades off Latency (L) vs Consistency (C); even CP systems must make this trade-off during normal operation."),
("Explain database migration best practices for production systems.", "Database migration best practices: (1) Schema migrations as code: use a migration tool (Flyway, Liquibase, Alembic, Rails ActiveRecord migrations, django.db.migrations); each schema change is a versioned, idempotent migration file committed to version control; migrations run automatically as part of deployment. (2) Backward compatibility: every migration deployed to production must be backward compatible with the version of application code currently running (because deployments are rolling -- not all instances update simultaneously); a migration that renames a column will break currently-running application instances that reference the old name. Safe pattern: Add new column; deploy new application code that writes to both old and new columns; backfill old data to the new column; deploy code that reads from only the new column; drop the old column. (3) Non-blocking operations: on large tables, operations like ADD COLUMN (with a default value in older Postgres), CREATE INDEX (without CONCURRENTLY), and ALTER COLUMN TYPE require a full table lock that blocks reads and writes for the duration; use: CREATE INDEX CONCURRENTLY (no lock); ADD COLUMN with nullable default (no rewrite in Postgres 11+); avoid ALTER TYPE on large tables -- instead create a new column. (4) Test migrations: run every migration against a production-sized data copy before running against production; measure execution time; if a migration takes more than 30 seconds on the test dataset, plan for a maintenance window or redesign. (5) Rollback plan: for every migration, document the rollback procedure; test that the rollback works before applying the migration."),
]

assert len(pairs) >= 13, f"Only {len(pairs)} pairs"
existing = sum(1 for _ in OUT.open()) if OUT.exists() else 0
print(f"Existing M pairs: {existing}")

with OUT.open("a") as f:
    for q, a in pairs:
        f.write(json.dumps({"messages": [
            {"role": "user", "content": q},
            {"role": "assistant", "content": a}
        ]}) + "\n")

total = sum(1 for _ in OUT.open())
print(f"Total M after fill2: {total}")
assert total >= 200, f"Still short: {total}"
print("M fill DONE -- ready to launch training")
